import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`wedding-planner-biz`,heroTitle:`Grow your wedding planning business in minutes`,heroSubtitle:`Perplexity Computer reviews your wedding planning site, packages, reviews, and local market, then builds a plan to attract more ideal couples.`,inputUrlCta:`Grow my business`,inputUrlPlaceholder:`yourweddingplanning.com`,inputUrlPrefill:`Go to {url} and run a growth audit for this wedding planning business. 1) Review the website, service packages, portfolio, testimonials, inquiry flow, pricing cues, and local visibility. 2) Analyze how clearly the planner communicates style, planning process, ideal couple, and value. 3) Benchmark strong local wedding planners and adjacent vendors for positioning, proof, packages, and lead capture. 4) Recommend the highest-impact fixes for more qualified inquiries and stronger consultation conversion. 5) Deliver a prioritized growth plan with rewritten copy, package recommendations, lead-magnet ideas, and next-step checklist.`,heroOverlaySteps:[`Reviewing your site, packages, portfolio, testimonials, and inquiry flow`,`Benchmarking strong local planners and adjacent vendors for proof and positioning`,`Finding the fixes most likely to improve qualified inquiries and consultations`,`Growth plan, package ideas, and website copy updates ready to use`],generatingSteps:[`Visiting {url} to review your wedding planning site and client journey`,`Designing an agent to benchmark local planners, packages, and proof signals`,`Configuring copy rewrites, package recommendations, and lead-capture ideas`,`Packaging the work into a prioritized growth plan for more ideal couples`],featureSectionTitle:`From portfolio visits to better-fit couples`,featureCardTitles:[`Connects to your planning stack`,`Outputs you can apply before booking season`],featureCardDescriptions:[`Computer breaks your growth audit into site review, package analysis, local benchmarking, and lead-capture recommendations, then routes each step to the right model.`,`Your website, CRM notes, galleries, reviews, Docs, and Sheets can feed one workflow so recommendations match your actual business.`,`Homepage rewrites. Package ideas. Lead-magnet concepts. Consultation-flow fixes. Computer gives you a practical plan to attract and convert more ideal couples.`],capabilitySectionTitle:`Your wedding business strategist, on demand`,capabilitySectionSubtitle:`Paste your site, step away, and come back to the changes most likely to grow qualified inquiries.`,capabilityCards:[{title:`Website and Package Audit`,description:`Computer can review your services, portfolio, testimonials, pricing cues, and inquiry flow to find conversion gaps.`},{title:`Local Market Benchmarking`,description:`Computer can compare nearby planners and adjacent vendors for positioning, packages, proof, and lead capture.`},{title:`Lead-Capture Improvements`,description:`Computer can recommend lead magnets, consultation CTAs, and package copy that speak to your ideal couples.`},{title:`Connect Your Tools`,description:`Computer can organize findings across your website, galleries, CRM notes, reviews, Docs, and Sheets.`},{title:`Remember Your Brand`,description:`Computer can remember your style, markets, package structure, and ideal couple so future plans stay aligned.`},{title:`Refresh the Plan`,description:`Computer can revisit your site and local market later to recommend updates before peak booking seasons.`}]});export{t as default};
